    /**
     * Run the database seeds.
     */
    public function run(): void
    {
        $this->command->info('Starting KYC data migration...');
        $this->command->getOutput()->progressStart(count($this->kycData));

        foreach ($this->kycData as $kycRecord) {
            try {
                $user = User::find($kycRecord['user_id']);
                if (!$user) {
                    $this->command->warn("User not found for KYC ID: {$kycRecord['id']}");
                    continue;
                }

                $kyc = Kyc::create([
                    'user_id' => $user->id,
                    'status' => (int)$kycRecord['is_confirmed'],
                    'verified_at' => $kycRecord['is_confirmed'] ? $kycRecord['confirmed_date'] : null,
                    'created_at' => $kycRecord['created_at'],
                    'updated_at' => $kycRecord['updated_at'],
                ]);

                $this->processProof($kyc, $kycRecord, 'identy');
                $this->processProof($kyc, $kycRecord, 'address');
                $this->processProof($kyc, $kycRecord, 'bank_ac');
                $this->processProof($kyc, $kycRecord, 'pan_card');

                $this->command->getOutput()->progressAdvance();
            } catch (\Exception $e) {
                $this->command->error("Failed to migrate KYC ID {$kycRecord['id']}: " . $e->getMessage());
            }
        }

        $this->command->getOutput()->progressFinish();
        $this->command->info('KYC migration completed.');
    }

    protected function processProof(Kyc $kyc, array $record, string $prefix): void
    {
        if (empty($record["{$prefix}_proof"])) return;

        $collection = match($prefix) {
            'identy' => 'identity_proof',
            'bank_ac' => 'bank_proof',
            'pan_card' => 'pan_proof',
            default => "{$prefix}_proof"
        };

        $this->addMediaToKyc(
            $kyc,
            $collection,
            $record["{$prefix}_proof"],
            $record["{$prefix}_proof_type"] ?? 'Document',
            $record["{$prefix}_proof_status"] ?? 0,
            $record["{$prefix}_proof_remarks"] ?? null
        );
    }

    protected function addMediaToKyc(
        Kyc $kyc,
        string $collection,
        string $filePath,
        string $type,
        string $status,
        ?string $remarks
    ): void {
        $fullUrl = $this->baseUrl . ltrim($filePath, '/');
        
        try {
            $media = $kyc->addMediaFromUrl($fullUrl)
                ->withCustomProperties([
                    'type' => $type,
                    'status' => (int)$status,
                    'remarks' => $remarks,
                ])
                ->toMediaCollection($collection);
                
            $this->command->info("Successfully added media from URL: {$fullUrl}");
        } catch (\Exception $e) {
            $this->command->error("Failed to add media from URL {$fullUrl}: " . $e->getMessage());
            
            // Fallback to local path if URL fails
            $this->tryLocalFallback($kyc, $collection, $filePath, $type, $status, $remarks);
        }
    }

    protected function tryLocalFallback(
        Kyc $kyc,
        string $collection,
        string $filePath,
        string $type,
        string $status,
        ?string $remarks
    ): void {
        $localPath = public_path('web_directory/kyc_proof/' . basename($filePath));
        
        if (file_exists($localPath)) {
            try {
                $kyc->addMedia($localPath)
                    ->withCustomProperties([
                        'type' => $type,
                        'status' => (int)$status,
                        'remarks' => $remarks,
                    ])
                    ->toMediaCollection($collection);
                    
                $this->command->info("Successfully added media from local path: {$localPath}");
            } catch (\Exception $e) {
                $this->command->error("Failed to add media from local path {$localPath}: " . $e->getMessage());
            }
        }
    }
}